/** Issue #3697 — provider audience definitions generated by the daily sync. */

import type {
  AdAudienceScope,
  PaidSocialPlatform,
} from "./adAudienceStages.ts";

export type AudienceDefinitionInput = {
  platform: PaidSocialPlatform;
  code: string;
  scope: AdAudienceScope;
  market: string;
  brandId: string | null;
  brandSlug: string | null;
  eventId: string | null;
  eventSlug: string | null;
  pixelId: string;
  eventEndsAt?: string | null;
};

export type AudienceDefinition = {
  name: string;
  windowDays: number;
  rule: Record<string, unknown>;
};

const WINDOWS: Record<string, number> = {
  M1: 30,
  M2: 60,
  M3: 30,
  M4: 90,
  M5: 14,
  M6: 395,
  M7: 180,
  M8: 365,
  M9: 30,
  S1: 30,
  S2: 30,
  S3: 14,
  S4: 395,
  S5: 365,
  S6: 30,
  T1: 30,
  T2: 30,
  T3: 14,
  T4: 395,
  T5: 365,
  T6: 30,
};

const CODE_PLATFORM: Record<string, PaidSocialPlatform> = Object.fromEntries([
  ...Array.from({ length: 9 }, (_, index) => [`M${index + 1}`, "meta"]),
  ...Array.from({ length: 6 }, (_, index) => [`S${index + 1}`, "snapchat"]),
  ...Array.from({ length: 6 }, (_, index) => [`T${index + 1}`, "tiktok"]),
]) as Record<string, PaidSocialPlatform>;

export const AUTOMATIC_EVENT_AUDIENCE_CODES = Object.freeze(
  {
    meta: ["M3", "M4", "M5", "M6"],
    snapchat: ["S2", "S3", "S4"],
    tiktok: ["T2", "T3", "T4"],
  } satisfies Record<PaidSocialPlatform, string[]>,
);

function eventPath(input: AudienceDefinitionInput): string {
  if (!input.brandSlug || !input.eventSlug) {
    throw new Error("event_audience_destination_missing");
  }
  return `/e/${input.brandSlug}/${input.eventSlug}`;
}

function scopeKey(input: AudienceDefinitionInput): string {
  if (input.scope === "event") return input.eventId ?? "event";
  if (input.scope === "brand") return input.brandId ?? "brand";
  return input.market.toUpperCase();
}

function metaRule(input: AudienceDefinitionInput): Record<string, unknown> {
  const path = eventPath(input);
  if (input.code === "M3") {
    return {
      source_type: "WEBSITE",
      pixel_id: input.pixelId,
      inclusions: [{
        event: "PageView",
        url: { operator: "i_contains", value: path },
      }],
      exclusions: [],
    };
  }
  if (input.code === "M4") {
    if (!input.brandSlug) throw new Error("brand_audience_destination_missing");
    return {
      source_type: "WEBSITE",
      pixel_id: input.pixelId,
      inclusions: [
        {
          event: "PageView",
          url: { operator: "i_contains", value: `/b/${input.brandSlug}` },
        },
        {
          event: "PageView",
          url: { operator: "i_contains", value: `/e/${input.brandSlug}/` },
        },
      ],
      exclusions: [],
    };
  }
  if (input.code === "M5") {
    return {
      source_type: "WEBSITE",
      pixel_id: input.pixelId,
      inclusions: [{ event: "InitiateCheckout", content_ids: [input.eventId] }],
      exclusions: [{ event: "Purchase", content_ids: [input.eventId] }],
    };
  }
  if (input.code === "M6") {
    return {
      source_type: "WEBSITE",
      pixel_id: input.pixelId,
      inclusions: [
        { event: "Purchase", content_ids: [input.eventId] },
        { event: "CompleteRegistration", content_ids: [input.eventId] },
      ],
      exclusions: [],
      event_ends_at: input.eventEndsAt ?? null,
    };
  }
  throw new Error(`audience_code_not_automatic:${input.code}`);
}

function snapRule(input: AudienceDefinitionInput): Record<string, unknown> {
  const event = input.code === "S2"
    ? "PAGE_VIEW"
    : input.code === "S3"
    ? "START_CHECKOUT"
    : input.code === "S4"
    ? "PURCHASE"
    : null;
  if (!event) throw new Error(`audience_code_not_automatic:${input.code}`);
  const eventRule: Record<string, unknown> = { eq: event };
  if (input.code !== "S2") eventRule.item_ids = [input.eventId];
  return {
    source_type: "PIXEL",
    pixel_id: input.pixelId,
    prefill: true,
    pixel_spec_object: { or: { event: [eventRule] } },
    ...(input.code === "S3"
      ? { exclude: { event: [{ eq: "PURCHASE", item_ids: [input.eventId] }] } }
      : {}),
    ...(input.code === "S4"
      ? { event_ends_at: input.eventEndsAt ?? null }
      : {}),
  };
}

function tiktokRule(input: AudienceDefinitionInput): Record<string, unknown> {
  const event = input.code === "T2"
    ? "ViewContent"
    : input.code === "T3"
    ? "InitiateCheckout"
    : input.code === "T4"
    ? "CompletePayment"
    : null;
  if (!event) throw new Error(`audience_code_not_automatic:${input.code}`);
  return {
    audience_sub_type: "WEBSITE",
    pixel_id: input.pixelId,
    inclusions: [{ event, content_id: input.eventId }],
    ...(input.code === "T3"
      ? {
        exclusions: [{ event: "CompletePayment", content_id: input.eventId }],
      }
      : { exclusions: [] }),
    ...(input.code === "T4"
      ? { event_ends_at: input.eventEndsAt ?? null }
      : {}),
  };
}

export function buildAudienceDefinition(
  input: AudienceDefinitionInput,
): AudienceDefinition {
  if (CODE_PLATFORM[input.code] !== input.platform) {
    throw new Error("audience_code_platform_mismatch");
  }
  if (!/^[A-Z]{2}$/.test(input.market.toUpperCase())) {
    throw new Error("audience_market_invalid");
  }
  if (!input.pixelId.trim()) throw new Error("audience_pixel_missing");
  if (
    input.scope === "event" && (!input.eventId || !input.brandId) ||
    input.scope === "brand" && !input.brandId
  ) {
    throw new Error("audience_scope_identity_missing");
  }
  const windowDays = WINDOWS[input.code];
  if (!windowDays) throw new Error("audience_code_unknown");
  const rule = input.platform === "meta"
    ? metaRule(input)
    : input.platform === "snapchat"
    ? snapRule(input)
    : tiktokRule(input);
  return {
    name: `Mingla ${input.code} ${input.scope} ${scopeKey(input)}`.slice(
      0,
      120,
    ),
    windowDays,
    rule,
  };
}

export function customerListCode(platform: PaidSocialPlatform): string {
  return platform === "meta" ? "M8" : platform === "snapchat" ? "S5" : "T5";
}
